-- Reading Archive v3.0 production schema
create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Member',role text not null default 'member' check(role in ('member','admin')),invited_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists invitations(id uuid primary key default gen_random_uuid(),code text unique not null,created_by uuid not null references auth.users(id),status text not null default 'unused' check(status in ('unused','used','revoked','expired','unused_claimed')),invited_email text,used_by uuid references auth.users(id),expires_at timestamptz,created_at timestamptz not null default now());
create table if not exists books(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,author text,status text not null default 'reading',progress numeric(5,2) not null default 0 check(progress between 0 and 100),current_page integer default 0,total_pages integer,last_read_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists reading_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,book_id uuid references books(id) on delete cascade,started_at timestamptz not null default now(),ended_at timestamptz,minutes integer default 0,pages_read integer default 0,created_at timestamptz not null default now());
create table if not exists excerpts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,book_id uuid references books(id) on delete set null,quote text not null,source text,why text,tags text[] not null default '{}',ai_analysis jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists ideas(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text not null default '',tags text[] not null default '{}',ai_analysis jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists writings(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,status text not null default 'draft',content text not null default '',ai_analysis jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists exercises(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,writing_id uuid references writings(id) on delete set null,source_note_id uuid references excerpts(id) on delete set null,title text not null,prompt text,skill text,submission text not null default '',status text not null default '未完成',score numeric(3,2),ai_feedback jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists training_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,skill text not null,score numeric(3,2) not null check(score between 0 and 5),source_type text not null,source_id uuid,feedback jsonb,created_at timestamptz not null default now());
create table if not exists skill_profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,skill text not null,mastery numeric(3,2) not null default 0 check(mastery between 0 and 5),ai_reason text,assessed_at timestamptz not null default now(),unique(user_id,skill));
create table if not exists writing_documents(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,writing_id uuid references writings(id) on delete set null,filename text not null,title text not null,format text not null check(format in ('TXT','DOCX','EPUB')),storage_bucket text not null default 'private-manuscripts',storage_path text not null,source_chars bigint not null default 0,chapter_count integer default 0,volume_count integer default 0,chunk_count integer default 0,status text not null default 'queued' check(status in ('queued','processing','completed','failed')),focus text,analysis_levels text[] not null default array['章节级','卷级','全书级'],error_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),analyzed_at timestamptz);
create table if not exists document_chunks(id uuid primary key default gen_random_uuid(),document_id uuid not null references writing_documents(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,sequence_no integer not null,chapter_label text,volume_label text,char_count integer not null default 0,status text not null default 'queued' check(status in ('queued','processing','completed','failed')),analysis jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(document_id,sequence_no));
create table if not exists document_reports(id uuid primary key default gen_random_uuid(),document_id uuid not null references writing_documents(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,level text not null check(level in ('chapter','volume','book')),scope_key text not null default '__all__',report jsonb not null default '{}',version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(document_id,level,scope_key,version));
create table if not exists analysis_jobs(id uuid primary key default gen_random_uuid(),document_id uuid not null references writing_documents(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,job_type text not null,status text not null default 'queued',progress integer not null default 0,error_message text,started_at timestamptz,finished_at timestamptz,created_at timestamptz not null default now());
create table if not exists growth_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,period_type text not null check(period_type in ('month','quarter','year')),period_start date not null,period_end date not null,metrics jsonb not null default '{}',summary text,created_at timestamptz not null default now(),unique(user_id,period_type,period_start));
create or replace function set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
do $$declare t text;begin foreach t in array array['profiles','books','excerpts','ideas','writings','exercises','writing_documents','document_chunks','document_reports'] loop execute format('drop trigger if exists trg_updated_%I on %I',t,t);execute format('create trigger trg_updated_%I before update on %I for each row execute function set_updated_at()',t,t);end loop;end$$;
create or replace function is_admin(uid uuid) returns boolean language sql security definer set search_path=public stable as $$select exists(select 1 from profiles where id=uid and role='admin')$$;
create or replace function protect_profile_role() returns trigger language plpgsql security definer set search_path=public as $$begin if old.role is distinct from new.role and not is_admin(auth.uid()) then raise exception 'role cannot be changed by member';end if;return new;end$$;
drop trigger if exists trg_profile_role_guard on profiles;create trigger trg_profile_role_guard before update on profiles for each row execute function protect_profile_role();
create or replace function claim_invitation(p_code text,p_email text) returns jsonb language plpgsql security definer set search_path=public as $$declare inv invitations%rowtype;begin select * into inv from invitations where code=upper(trim(p_code)) and status='unused' for update;if not found then return jsonb_build_object('error','邀请码无效、已使用或已撤销');end if;if inv.expires_at is not null and inv.expires_at<now() then update invitations set status='expired' where id=inv.id;return jsonb_build_object('error','邀请码已过期');end if;if inv.invited_email is not null and lower(inv.invited_email)<>lower(trim(p_email)) then return jsonb_build_object('error','该邀请码绑定了其他邮箱');end if;update invitations set status='unused_claimed' where id=inv.id;return jsonb_build_object('id',inv.id);end$$;
alter table profiles enable row level security;alter table invitations enable row level security;alter table books enable row level security;alter table reading_sessions enable row level security;alter table excerpts enable row level security;alter table ideas enable row level security;alter table writings enable row level security;alter table exercises enable row level security;alter table training_records enable row level security;alter table skill_profiles enable row level security;alter table writing_documents enable row level security;alter table document_chunks enable row level security;alter table document_reports enable row level security;alter table analysis_jobs enable row level security;alter table growth_records enable row level security;
drop policy if exists profiles_select_self on profiles;create policy profiles_select_self on profiles for select using(auth.uid()=id);
drop policy if exists profiles_update_self on profiles;create policy profiles_update_self on profiles for update using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists invitations_admin on invitations;create policy invitations_admin on invitations for all using(is_admin(auth.uid())) with check(is_admin(auth.uid()));
do $$declare t text;begin foreach t in array array['books','reading_sessions','excerpts','ideas','writings','exercises','training_records','skill_profiles','writing_documents','document_chunks','document_reports','analysis_jobs','growth_records'] loop execute format('drop policy if exists %I_own on %I',t,t);execute format('create policy %I_own on %I for all using(auth.uid()=user_id) with check(auth.uid()=user_id)',t,t);end loop;end$$;
insert into storage.buckets(id,name,public) values('private-manuscripts','private-manuscripts',false) on conflict(id) do update set public=false;
drop policy if exists manuscript_select_own on storage.objects;drop policy if exists manuscript_insert_own on storage.objects;drop policy if exists manuscript_update_own on storage.objects;drop policy if exists manuscript_delete_own on storage.objects;
create policy manuscript_select_own on storage.objects for select using(bucket_id='private-manuscripts' and (storage.foldername(name))[1]=auth.uid()::text);create policy manuscript_insert_own on storage.objects for insert with check(bucket_id='private-manuscripts' and (storage.foldername(name))[1]=auth.uid()::text);create policy manuscript_update_own on storage.objects for update using(bucket_id='private-manuscripts' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='private-manuscripts' and (storage.foldername(name))[1]=auth.uid()::text);create policy manuscript_delete_own on storage.objects for delete using(bucket_id='private-manuscripts' and (storage.foldername(name))[1]=auth.uid()::text);
